ss = fn("split_sections")
doc = "Contrat de location\n\nArticle 1 - Loyer\nLe loyer est de 900 TND.\n\nArticle 2 - Caution\nDeux mois.\n## Annexe\n\nالمادة 3 الضمان\nشهرين."
check("split_sections: text before the first heading gets ''", lambda: ss(doc)[0] == ("", "Contrat de location"))
check("split_sections: Article, Markdown and المادة headings", lambda: [h for h, _ in ss(doc)] == ["", "Article 1 - Loyer", "Article 2 - Caution", "المادة 3 الضمان"])
check("empty sections are dropped (## Annexe has no body)", lambda: all(b for _, b in ss(doc)) and "Annexe" not in [h for h, _ in ss(doc)])
ch = fn("content_hash")
check("content_hash: 12 hex chars, ignores whitespace differences", lambda: len(ch("a b")) == 12 and ch("Deux  mois.\n") == ch("Deux mois.") and ch("a") != ch("b"))
mk = fn("make_chunks")
cs = lambda: mk({"id": "bail7", "title": "Bail type", "text": doc}, lambda b: [b], lambda t: "ar" if "ش" in t else "fr")
check("make_chunks: ids count across the document", lambda: [c["id"] for c in cs()] == ["bail7-c0", "bail7-c1", "bail7-c2", "bail7-c3"])
check("make_chunks: metadata on every chunk", lambda: (lambda c: c["doc_id"] == "bail7" and c["section"] == "Article 2 - Caution" and c["lang"] == "fr" and c["n_chars"] == len("Deux mois.") and c["hash"] == ch("Deux mois."))(cs()[2]))
check("make_chunks: embed_text carries title and section", lambda: cs()[1]["embed_text"] == "Bail type > Article 1 - Loyer\nLe loyer est de 900 TND." and cs()[0]["embed_text"] == "Bail type\nContrat de location")
check("make_chunks: lang per chunk", lambda: cs()[3]["lang"] == "ar")
dd = fn("dedupe_chunks")
check("dedupe_chunks keeps the first copy and counts the rest", lambda: (lambda r: [c["id"] for c in r[0]] == ["a", "c"] and r[1] == 1)(dd([{"id": "a", "hash": "h1"}, {"id": "b", "hash": "h1"}, {"id": "c", "hash": "h2"}])))
